import {evidence} from './case-data.js';
import {mountHybrid} from './editorial-studio.js';
const names=['Cinematic Editorial','Precision Intelligence Studio','Documentary Evidence Lens','Modern Production Command','Film Production Atelier','Radical Clarity','Editorial Intelligence Studio'];
const keys=['editorial','studio','lens','command','atelier','clarity','editorial-studio'];
const qs=new URLSearchParams(location.search);let concept=Math.max(0,keys.indexOf(qs.get('concept')??'editorial'));
let screen=qs.get('screen')??'opening',scene=47,unit=1,staged=null,verified=false,notice='',subview='',filter='all';
const storageKey=()=>`beforeroll-design-v1-${keys[concept]}`;
let reviews=JSON.parse(localStorage.getItem(storageKey())??'[]');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clauses=evidence.case.permit.split('\n');
const record=(s=scene,u=unit)=>evidence.recording.scenes.find(x=>x.sceneId==='S'+s).scan.results[u];
const button=(label,action,cls='')=>`<button class="${cls}" data-go="${action}">${label}</button>`;
const label=(n,title)=>`<div class="eyebrow"><span>${n}</span> ${title}</div>`;
const quote=(u=unit)=>`<blockquote><p>“${esc(clauses[u])}”</p><cite>HW-18 · original paragraph ${u+1} · revision 1</cite></blockquote>`;
const model=()=>`<div class="model">${label('02','Clocked intelligence')}<h3>${unit===1?'Different words. A consequential link.':esc(record().finding.title)}</h3><p>${unit===1?'The call sheet says “wheeled dolly”. The permit says “pressure-bearing wheeled camera platforms”. Inspect their relationship before planning the move.':'Compare this model finding with the exact passage and scene scope.'}</p><small>Design-authored reading guide above. Recorded provider finding below.</small><p class="recorded">${esc(record().finding.title)}</p><details><summary>Recorded model output</summary><p>${esc(record().finding.explanation)}</p><dl><dt>Activity link (raw return)</dt><dd>${record().finding.relevance}</dd><dt>Scene grant (raw return)</dt><dd>${record().finding.grant}</dd></dl><p>Uncalibrated model returns, not confidence or documentary authority.</p><code>${esc(record().finding.code)}</code></details></div>`;
const plan=()=>`<div class="plan">${label('01','Planned activity')}<div class="scene-heading"><span class="scene-number">${scene}</span><div><h2>${scene===47?'A tracking shot over the mosaic':'A second travelling shot'}</h2><p>Riverton Archive Atrium · ${scene===47?'10:05–10:25':'11:10–11:30'}</p></div></div><p>${esc(evidence.case.scenes[scene===47?0:1].split(' | ')[3])}</p><a class="next-action-jump" href="#next-action">Next human action ↓</a></div>`;
const source=()=>`<div class="source">${label('03','Documentary evidence')}${quote()}${button('Compare addendum and request →','exception','text-button')}<p class="quiet">Original wording is evidence. The application does not authenticate signatures.</p></div>`;
const action=()=>`<div class="action" id="next-action" tabindex="-1">${label('04','Human action')}<h3>${scene===47?'Check the scoped exception and its conditions.':'Obtain an issued amendment for Scene 48.'}</h3><p>${scene===47?'AD-4 names Scene 47. Protective boards and an on-site registrar still need human verification.':'The emailed extension is explicitly unsigned. Similar equipment and general consent do not extend AD-4.'}</p>${button('Record source review →','review','primary')} ${button('Inspect all evidence','depth','text-button')}</div>`;
const scenes=()=>`<nav class="scene-picker" aria-label="Scenes">${[47,48].map(s=>`<button data-scene="${s}" aria-pressed="${scene===s}"><strong>Scene ${s}</strong><span>${s===47?'10:05 · Tracking carriage':'11:10 · Rolling platform'}</span><small>${s===47?'Scoped addendum to check':'Unsigned request only'}</small></button>`).join('')}</nav>`;
const nav=()=>`<nav class="product-nav" aria-label="Workspace">${[['opening','Production'],['discovery','Scenes'],['workflow','Work'],['depth','Documents & history']].map(([id,t])=>`<button data-go="${id}" aria-current="${screen===id?'page':'false'}">${t}</button>`).join('')}</nav>`;
const top=()=>`<header class="brandbar"><a class="brand" href="?concept=${keys[concept]}">BeforeRoll<span class="brand-dot">.</span></a><span class="production-name">Riverton Archive <small>Fictional production / 08 Nov 2026</small></span>${nav()}</header>`;
const caption=()=>`<div class="context"><span>Archive floor / U01</span><span>Recorded Clocked example · older request contract · no new calls</span></div>`;
function opening(){
 const intro=`<div class="intro">${label('Before the first take','Film-production intelligence')}<h1>The shot is planned.<br><em>Is the paperwork?</em></h1><p>Clocked connects what your crew plans to do with what the permit actually says. Follow the evidence. Decide what needs to happen next.</p>${button('Investigate Scene 47 →','discovery','primary')} ${button('Open production work','workflow','text-button')}<small>Fictional source documents · genuine recorded model outputs</small></div>`;
 const preview=`<article class="opening-preview">${label('A live question in this example','Scene 47')}<h2>Wheeled dolly <span class="link-arrow">↔</span><br>pressure-bearing platform</h2><p>One movement. Two vocabularies.<br>A permit condition worth investigating.</p><div class="preview-quote">“Pressure-bearing wheeled camera platforms must not cross the original tesserae…” <small>Excerpt · HW-18, paragraph 2</small></div><div class="preview-foot"><span>Clocked found the relationship</span>${button('See the source ↗','discovery','text-button')}</div></article>`;
 if(concept===1)return `<div class="studio-open">${intro}<div class="studio-snapshot"><div class="windowline">Scene intelligence / source-linked review</div>${preview}<div class="snapshot-bottom"><span>01 Planned activity</span><span>02 Clocked</span><span>03 Original evidence</span><span>04 Human action</span></div></div></div>`;
 if(concept===2)return `<div class="lens-intro">${intro}</div><div class="lens-opening"><div>${label('Call sheet','Intention')}<h2>“Follow the performer on a wheeled dolly…”</h2><p>Scene 47 · intended activity</p></div><div class="lens-bridge">Clocked<br>connects<br>↔</div><div>${label('Permit HW-18','Condition')}<h2>“Pressure-bearing wheeled camera platforms…”</h2><p>Paragraph 2 · original source language</p></div></div>${button('Inspect the relationship →','discovery','primary')}`;
 if(concept===3)return `<div class="command-open">${intro}<aside class="callboard"><h2>08 November · Archive Atrium</h2><div><b>10:05</b><span>47 / Tracking shot<br><small>Check boards and registrar</small></span></div><div><b>11:10</b><span>48 / Travelling shot<br><small>Issued extension missing</small></span></div>${button('Open the day’s work →','workflow','primary')}</aside></div>`;
 if(concept===4)return `<div class="atelier-open"><div class="folio-label">Riverton Archive<br>Production folio / 01</div>${intro}${preview}</div>`;
 if(concept===5)return `<div class="clarity-open">${intro}<div class="question-preview"><span>Start with one meaningful question</span><h2>Does Scene 47’s dolly move fall under the floor restriction?</h2>${button('Follow the evidence →','discovery','primary')}</div></div>`;
 return `<div class="editorial-open">${intro}${preview}</div><div class="opening-index"><span>01 / Understand the plan</span><span>02 / Investigate the link</span><span>03 / Act on the evidence</span></div>`;
}
function discovery(){
 const heading=`<div class="page-heading"><div>${label('Scene intelligence','Source → action')}<h1>${concept===5?'What needs checking?':'A camera move. A floor restriction.'}</h1></div>${scenes()}</div>`;
 if(concept===0)return `${heading}<div class="editorial-discovery"><div class="editorial-story">${plan()}${model()}</div><aside class="editorial-source">${source()}${action()}</aside></div>`;
 if(concept===1)return `<div class="precision-layout"><aside class="precision-rail"><h2>Scene register</h2>${scenes()}<p>2 scenes · 8 recorded checks</p>${button('Production work','workflow')}</aside><section>${plan()}<div class="precision-pair">${model()}${source()}</div>${action()}</section></div>`;
 if(concept===2)return `${heading}<div class="lens-discovery">${plan()}<div class="lens-relation">${model()}</div>${source()}</div>${action()}`;
 if(concept===3)return `${heading}<div class="command-detail"><aside><h2>Work for Scene ${scene}</h2><ol><li>Read linked restriction</li><li>Compare scope</li><li>Record source review</li></ol>${action()}</aside><section>${plan()}${model()}${source()}</section></div>`;
 if(concept===4)return `${heading}<div class="folio-spread"><div class="folio-page">${plan()}${source()}</div><aside class="margin-notes"><span class="annotation">Coordinator’s margin</span>${model()}${action()}</aside></div>`;
 return `<div class="clarity-discovery">${scenes()}${plan()}<div class="clarity-thread">${model()}${source()}${action()}</div></div>`;
}
function exception(){return `<div class="page-heading"><div>${label('Documentary exception','Scope matters')}<h1>Same floor.<br>Different documentary position.</h1><p>A scoped addendum is not a blanket permission.</p></div></div><div class="exception-grid"><article class="exception issued"><span class="state">Document says “SIGNED ADDENDUM”</span><h2>47 <small>Explicitly named</small></h2>${quote(2)}<h3>Check the conditions</h3><p>Protective boards and an on-site registrar must be present throughout. Source language is not signature authentication or confirmation of fulfilment.</p><button data-investigate="47" class="primary">Investigate Scene 47 →</button></article><article class="exception request"><span class="state">Document says “not issued”</span><h2>48 <small>Request only</small></h2>${quote(3)}<h3>Request an issued amendment</h3><p>The extension request does not establish permission for Scene 48. Do not carry Scene 47’s scoped exception across.</p><button data-investigate="48" class="primary">Investigate Scene 48 →</button></article></div><div class="exception-bottom">${label('Human investigation','Separate from the model')}<p>Clocked outputs remain in each exact scene/source record. These documentary distinctions are design-authored reading guides to the original text.</p>${button('Inspect recorded findings','depth','text-button')}</div>`;}
function workflow(){
 const items=[['47','Verify protective boards and registrar','AD-4 · paragraph 3','Human verification needed'],['48','Obtain an issued extension','HW-18 · paragraph 4','Source needed'],['Production','Review document role and scope','HW-18 · revision 1','Review needed']];
 const rows=items.filter(x=>filter!=='48'||x[0]==='48').map(x=>`<button class="work-row" data-investigate="${x[0]==='48'?48:47}"><b>${x[0]}</b><span><strong>${x[1]}</strong><small>${x[2]}</small></span><span class="state">${x[3]}</span><span>↗</span></button>`).join('');
 const head=`<div class="page-heading"><div>${label('Production work','A coherent follow-through')}<h1>${concept===3?'The day’s unresolved work.':'Keep the shoot moving.'}</h1><p>Human work follows documentary evidence. Completion never means filming clearance.</p></div>${button('Inspect review history','depth','text-button')}</div>`;
 const list=`<div class="work-list"><div class="work-toolbar"><h2>Outstanding conditions</h2><label>Show <select id="work-filter"><option value="all" ${filter==='all'?'selected':''}>All scenes</option><option value="48" ${filter==='48'?'selected':''}>Scene 48</option></select></label></div>${rows}</div>`;
 const stages=`<nav class="workflow-links" aria-label="Production capabilities">${[['documents','Import & verify sources'],['discovery','Analyze & investigate scenes'],['review','Human reviews'],['revision','Reconcile revisions'],['depth','History & evidence'],['export','Export & recovery']].map(([id,t],i)=>button(`<span>0${i+1}</span>${t} ↗`,id)).join('')}</nav>`;
 if(concept===3)return `${head}<div class="command-board"><div><div class="day-label">Sunday / 08 November 2026</div>${list}</div><aside><h2>Production pathways</h2>${stages}</aside></div>`;
 if(concept===4)return `${head}<div class="folio-spread"><div class="folio-page">${list}</div><aside class="margin-notes"><h2>Folio index</h2>${stages}</aside></div>`;
 if(concept===5)return `${head}<div class="clarity-work">${list}<details><summary>All production capabilities</summary>${stages}</details></div>`;
 return `${head}<div class="workflow-layout">${list}<aside>${stages}</aside></div>`;
}
function depth(){const r=record();return `<div class="page-heading"><div>${label('Evidence depth','Exact sources remain reachable')}<h1>A finding you can trace.</h1><p>Scene ${scene} · HW-18 · original paragraph ${unit+1} · revision 1</p></div>${button('Return to scene →','discovery','text-button')}</div><div class="evidence-layout"><aside><h2>Source passages</h2><nav class="unit-nav">${clauses.map((q,i)=>`<button data-unit="${i}" aria-pressed="${i===unit}"><b>0${i+1}</b><span>${['Location consent','Floor restriction','Scene 47 addendum','Scene 48 request'][i]}</span></button>`).join('')}</nav>${scenes()}${button('Document register','documents')}${button('Review history','history')}</aside><section class="document-page">${label('Original text','HW-18')}${quote()}<hr><h2>Recorded Clocked finding</h2><p>${esc(r.finding.title)}</p><p>${esc(r.finding.explanation)}</p><details><summary>Model fields and source identity</summary><dl><dt>Activity link</dt><dd>${r.finding.relevance}</dd><dt>Scene grant</dt><dd>${r.finding.grant}</dd><dt>Original source SHA-256</dt><dd><code>${evidence.case.permitSha256}</code></dd><dt>Scene source SHA-256</dt><dd><code>${evidence.case.sceneSha256[scene===47?0:1]}</code></dd><dt>Recorded request SHA-256</dt><dd><code>${r.requestHash}</code></dd></dl><pre>${esc(JSON.stringify(r.modelAnswers,null,2))}</pre><p>Owner-recorded · different request contract · uncalibrated returns · no new API call.</p></details><details><summary>Complete original source</summary>${clauses.map(q=>`<p>${esc(q)}</p>`).join('')}</details>${button('Record source review →','review','primary')}</section></div>`;}
function review(){return `<div class="review-layout"><section>${label('Exact source review',`Scene ${scene} / paragraph ${unit+1}`)}<h1>Your decision.<br>Attached to the source.</h1>${quote()}<p>Prototype human work is stored separately from the frozen recording.</p>${button('Back to scene','discovery','text-button')}</section><form id="review-form"><h2>Record a human review</h2><label>Your name<input name="reviewer" required maxlength="150" autocomplete="off" value="${staged?.scene===scene&&staged?.unit===unit?esc(staged.reviewer):''}"></label><label>Decision<select name="decision"><option>Needs source evidence</option><option>Acknowledged for follow-up</option><option>Human-reviewed (not clearance)</option></select></label><label>Rationale and next action<textarea name="reason" required minlength="8" maxlength="3000" rows="5" placeholder="What did you verify, and what still needs to happen?">${staged?.scene===scene&&staged?.unit===unit?esc(staged.reason):''}</textarea></label><button class="primary" type="submit">Stage exact-source review →</button><small>No signature authentication or filming clearance is created.</small></form></div>`;}
function previewReview(){return `<div class="narrow">${label('Review session','Prototype-only transaction')}<h1>Inspect before applying.</h1>${staged?`<h2>Scene ${staged.scene} · paragraph ${staged.unit+1}</h2>${quote(staged.unit)}<p><b>${esc(staged.decision)}</b> · ${esc(staged.reviewer)}</p><p>${esc(staged.reason)}</p><p>Bound to U01 revision 1, exact scene and original source hash.</p>${button(verified?'Verified exact selection':'Verify selected source','verify',verified?'':'primary')} ${button('Apply prototype review','commit',verified?'primary':'')} ${button('Edit review','review','text-button')}`:'No review staged. Return to a scene and record a reasoned review.'}<p>Applying affects this concept’s local prototype state only.</p></div>`;}
function documents(){return `<div class="narrow"><h1>Originals, with context.</h1><article class="document-page"><h2>HW-18 · Archive filming consent</h2><p>One original document · four passages · revision 1</p><p>Contains general consent, a restriction, scoped addendum language and an unsigned request. Roles and authenticity still require human review.</p>${button('Read all passages','depth','primary')} ${button('Preview a revision','revision')}</article><article class="document-page"><h2>Call sheet · Scenes 47 and 48</h2>${evidence.case.scenes.map(x=>`<p>${esc(x)}</p>`).join('')}</article><p>Prototype intake is a navigation study. Use accepted production intake for actual file import and transcription verification.</p></div>`;}
function history(){return `<div class="narrow"><h1>Reviews and provenance.</h1><p>Recorded model evidence is unchanged. Human entries below are explicitly prototype interactions.</p><article class="document-page"><h2>Original recording</h2><p>U01 · 8 genuine historical requests · 0 new calls in this study.</p>${button('Inspect exact recorded source','depth','text-button')}</article>${reviews.length?reviews.map(x=>`<article class="document-page"><span class="state">Prototype human review</span><h2>Scene ${x.scene} · paragraph ${x.unit+1}</h2><p>${esc(x.decision)} · ${esc(x.reviewer)}</p><p>${esc(x.reason)}</p><small>${esc(x.at)}</small></article>`).join(''):'<p>No prototype reviews yet. Record one from the scene workspace.</p>'}${button('Return to work','workflow','primary')}</div>`;}
function revision(){return `<div class="narrow"><h1>A changed source changes the work.</h1><p class="state">Interaction storyboard · no replacement file or new Clocked result</p><p>The accepted app requires an exact file preview before commit. This prototype demonstrates the presentation using a hypothetical revision.</p><div class="document-page"><h2>Review impact before replacing HW-18</h2><p>Retire affected findings and source reviews. Preserve originals and historical records. Keep unaffected evidence current.</p>${subview==='impact'?`<h3>Impact preview</h3><p>Changed paragraphs need renewed checks. Old reviews remain historical and must not reappear as current if old bytes return.</p><p>No numeric impact is invented here. The implementation must render the server’s actual retained, retired and added counts.</p>${button('Return to source register','documents','primary')}`:button('Preview revision impact','impact','primary')}</div></div>`;}
function exportView(){return `<div class="narrow"><h1>Take the evidence with you.</h1><p>Production exports include current and historical source-bound evidence. These prototypes export only your design-review notes.</p><div class="document-page"><h2>Prototype review notes</h2><p>${reviews.length} prototype human reviews · frozen Clocked recording unchanged</p>${button('Download prototype notes','download','primary')}</div><details><summary>Production recovery experience</summary><p>Select encrypted backup → verify passphrase and inventory → inspect originals and journals → restore a separate copy. Wrong passphrase or damaged backup must leave current work untouched. Unknown-billing attempts remain fenced.</p><p>This is a design storyboard. No encrypted backup is imported or restored here.</p></details></div>`;}
function render(){document.body.className=keys[concept];document.title=`${names[concept]} · BeforeRoll design study`;
 document.querySelector('#lab').innerHTML=`<div class="lab"><label>Design <select id="concept">${names.map((n,i)=>`<option value="${i}" ${i===concept?'selected':''}>${String.fromCharCode(65+i)} · ${n}</option>`).join('')}</select></label><nav aria-label="Comparable screens">${[['opening','1 First impression'],['discovery','2 Discovery'],['exception','3 Exception'],['workflow','4 Workflow'],['depth','5 Evidence']].map(([s,n])=>`<button data-go="${s}" aria-pressed="${s===screen}">${n}</button>`).join('')}</nav><span>Design sandbox · no live API</span></div>`;
 if(concept===6){mountHybrid({screen,onScreenChange:next=>{screen=next;document.querySelectorAll('#lab [data-go]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.go===next)));}});return;}
 const views={opening,discovery,exception,workflow,depth,review,preview:previewReview,documents,history,revision,export:exportView};
 document.querySelector('#app').innerHTML=`${top()}${caption()}<main id="main" tabindex="-1">${notice?`<div role="status" class="notice">${esc(notice)}</div>`:''}${(views[screen]??opening)()}</main><footer><span>BeforeRoll / ${names[concept]}</span><span>Model judgment ≠ documentary authority ≠ human confirmation</span></footer>`;
 historyURL();
}
function historyURL(){const url=new URL(location);url.searchParams.set('concept',keys[concept]);url.searchParams.set('screen',screen);window.history.replaceState(null,'',url);}
function move(next){screen=next;notice='';render();document.querySelector('#main').focus();window.scrollTo(0,0);}
document.addEventListener('change',e=>{if(e.target.id==='concept'){concept=+e.target.value;reviews=JSON.parse(localStorage.getItem(storageKey())??'[]');staged=null;verified=false;move('opening');}if(e.target.id==='work-filter'){filter=e.target.value;render();}});
document.addEventListener('submit',e=>{if(e.target.id!=='review-form')return;e.preventDefault();const data=new FormData(e.target);staged={scene,unit,reviewer:data.get('reviewer'),decision:data.get('decision'),reason:data.get('reason'),sourceHash:evidence.case.permitSha256};verified=false;move('preview');});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.scene){scene=+b.dataset.scene;render();return;}if(b.dataset.unit){unit=+b.dataset.unit;render();return;}if(b.dataset.investigate){scene=+b.dataset.investigate;unit=scene===48?3:2;move('discovery');return;}
 const go=b.dataset.go;if(!go)return;
 if(go==='verify'){verified=Boolean(staged);notice='Exact scene, paragraph and original source identity verified for this prototype review.';render();return;}
 if(go==='commit'){if(!verified){notice='Verify the exact source before applying this review.';render();return;}reviews.push({...staged,at:new Date().toISOString(),prototypeOnly:true});localStorage.setItem(storageKey(),JSON.stringify(reviews));staged=null;verified=false;screen='history';notice='Prototype review saved. The original Clocked recording is unchanged.';render();return;}
 if(go==='impact'){subview='impact';render();return;}
 if(go==='download'){const blob=new Blob([JSON.stringify({prototypeOnly:true,concept:names[concept],reviews},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='beforeroll-design-notes.json';a.click();URL.revokeObjectURL(a.href);notice='Prototype notes exported; this is not a production evidence pack.';render();return;}
 move(go);
});render();
